#include <bits/stdc++.h>
using namespace std;

void apply_op(vector<int>& p, int x, int y) {
    int n = p.size();
    // [0..x-1] [x..n-y-1] [n-y..n-1] -> [n-y..n-1] [x..n-y-1] [0..x-1]
    vector<int> np;
    for (int i = n-y; i < n; i++) np.push_back(p[i]);
    for (int i = x; i < n-y; i++) np.push_back(p[i]);
    for (int i = 0; i < x; i++) np.push_back(p[i]);
    p = np;
}

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    for(int placed = 0; placed < n-2; placed++){
        int pos = -1;
        for(int i = placed; i < n; i++) if(p[i] == placed+1){ pos = i; break; }
        if(pos == placed) continue;

        // Step 1: bring element at pos to position n-1
        if(pos != n-1){
            // We want to move p[pos] to end.
            // Use x = pos+1, y = n-1-pos. Then x+y = pos+1+n-1-pos = n. Need x+y < n. So this doesn't work.
            // Use x = pos+1, y = n-2-pos when pos < n-2. Then x+y = n-1 < n. Middle has 1 element.
            // Result: [n-2-pos..n-1] [pos+1..pos+1] [0..pos] -> element at pos goes to end (position n-1 in new array is p[pos])
            // Wait: new array = p[n-y..n-1] + p[x..n-y-1] + p[0..x-1]
            // x=pos+1, y=n-2-pos: suffix=p[pos+2..n-1], middle=p[pos+1..pos+1], prefix=p[0..pos]
            // new = p[pos+2..n-1] + p[pos+1] + p[0..pos]
            // p[pos] is in position n-1 of new array (last element of prefix p[0..pos] is p[pos])
            if(pos < n-2){
                int x = pos+1, y = n-2-pos;
                ops.push_back({x, y});
                apply_op(p, x, y);
                pos = n-1;
            } else {
                // pos == n-2. Use x=1, y=1 if n>3, swaps first and last
                // Actually x=n-2, y=1: x+y=n-1<n. suffix=p[n-1], middle=empty? No middle=p[n-2..n-2] wait
                // x=pos, y=1: x+y=pos+1=n-1<n. suffix=p[n-1], middle=p[pos..n-2], prefix=p[0..pos-1]
                // new = p[n-1] + p[pos..n-2] + p[0..pos-1]. Element at pos=n-2 is at position 1+(n-2-pos)=1+0=1... no at position 1 in middle? 
                // Actually element at n-2 stays in middle. Not helpful.
                int x = pos+1, y = 1; // x=n-1, y=1, x+y=n. Not valid.
                x = 1; y = 1; // swap first and last, middle stays
                ops.push_back({x, y});
                apply_op(p, x, y);
                for(int i=placed;i<n;i++) if(p[i]==placed+1){pos=i;break;}
                if(pos!=n-1 && pos<n-2){ int xx=pos+1,yy=n-2-pos; ops.push_back({xx,yy}); apply_op(p,xx,yy); pos=n-1; }
            }
        }
        if(pos==placed) continue;
        // Step 2: element at n-1, bring to position 'placed'
        // x=placed+1, y=1: x+y=placed+2. Need <n, so placed<n-2 (true since placed<n-2 in loop)
        // new = p[n-1] + p[placed+1..n-2] + p[0..placed]
        // p[n-1] goes to position 0... we want position placed
        // Actually we need x=placed, y=1 if placed>0: new = p[n-1] + p[placed..n-2] + p[0..placed-1]. Element goes to pos 0, not placed.
        // Try: x=1, y=n-1-placed: suffix=p[placed+1..n-1], middle=p[1..placed], prefix=p[0]
        // new = p[placed+1..n-1] + p[1..placed] + p[0]. Element at n-1 goes to position (n-1-placed-1)=n-2-placed. Not placed.
        // Hmm. Let me think differently: we want the last element to end up at position 'placed'.
        // After op(x,y): prefix p[0..x-1] goes to positions n-x..n-1. So to put element at n-1 into position placed:
        // It's in suffix. Suffix p[n-y..n-1] goes to positions 0..y-1. So if element at n-1, it goes to position y-1. Set y-1=placed => y=placed+1.
        // Need x+y<n => x<n-placed-1. x>=1. So x=1, y=placed+1. x+y=placed+2<=n-1 when placed<=n-3.
        {
            int x=1, y=placed+1;
            if(x+y<n){
                ops.push_back({x,y});
                apply_op(p,x,y);
            }
        }
    }

    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
